      origins: [`${store.lat},${store.lng}`], destinations: [`${lat},${lng}`], key: process.env.MAPS_KEY!,
    } });
    const el = matrix.data.rows[0].elements[0];
    if (el.status !== 'OK') return h.response({ error: 'Address not reachable' }).code(422);
    if (el.distance.value > 12000) return h.response({ error: 'Outside delivery area' }).code(422);
    const prepMinutes = store.openOrders > 20 ? 25 : 15;
    const driveMinutes = Math.ceil(el.duration_in_traffic?.value ?? el.duration.value) / 60;
    const now = new Date();
    const hour = now.getHours();
    const rushBuffer = (hour >= 12 && hour < 14) || (hour >= 18 && hour < 21) ? 10 : 0;
    const min = Math.ceil(prepMinutes + driveMinutes + rushBuffer);
    return { fromMinutes: min, toMinutes: min + 15 };
  },
